Q: Does jQuery have a JSON/javascript object to HTML pretty print function similar to PHP&#39;s var_dump? A: <p>you can do it without jquery, just did this tonight. only tenet is this must be ran in the main thread in a browser; you need access to the DOM because it leverages the behavior of elements changing when their innerHTML is updated. here, HTH anyone who's in here in 2026 or later:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const prettyPrint = (mkp, tabWidth) =&gt; {

  /* use div to parse the string as html */
  let div = document.createElement("div");
  div.innerHTML = mkp;

  /* recursive function */
  const recurse = (indent, tabWidth, el) =&gt; {

    /* no children or self-closing elems like &lt;img&gt; */
    if( !el.children || !el.children.length ){
      return " ".repeat( tabWidth * indent ) + el.outerHTML + "\n";
    }

    /* get opening and closjng tags */
    let [ openingTag, closingTag ] = el.outerHTML.split( el.innerHTML );

    /* start with opening tag, then newline */
    let str = " ".repeat( tabWidth * indent ) + openingTag + "\n";

    /* for each child, recurse, adding 1 to indent */
    for( let child of el.children ){
      str += recurse( indent + 1, tabWidth, child );
    }

    /* close the tag */
    str += " ".repeat( tabWidth * indent ) + closingTag + "\n";

    return str;

  };

  /* return result plus some minor formatting to remove the temp div and de-indent */
  return recurse( 0, tabWidth, div ).match(/.+/g).slice(1,-1).map((l)=&gt;l.slice(tabWidth)).join("\n");

};

let testDiv = document.createElement( "div" );
testDiv.appendChild( document.createElement( "h1" ) ).textContent = "hello";
testDiv.appendChild( new Image() ).src = "kdjfdsf";
let ul = testDiv.appendChild( document.createElement( "ul" ) );
ul.appendChild( document.createElement( "li" ) );
